azure_endpoints.tfType:
map(object({
    name               = string
    target_resource_id = string
    enabled            = optional(bool, true)
    weight             = optional(number)
    priority           = optional(number)
    endpoint_location  = optional(string)
    geo_mapping        = optional(list(string))
    always_serve       = optional(string, "Disabled")
    custom_headers = optional(list(object({
      name  = string
      value = string
    })), [])
    subnets = optional(list(object({
      first = string
      last  = optional(string)
      scope = optional(number)
    })), [])
  }))

external_endpoints.tfType:
map(object({
    name              = string
    target            = string
    enabled           = optional(bool, true)
    weight            = optional(number)
    priority          = optional(number)
    endpoint_location = optional(string)
    geo_mapping       = optional(list(string))
    always_serve      = optional(string, "Disabled")
    custom_headers = optional(list(object({
      name  = string
      value = string
    })), [])
    subnets = optional(list(object({
      first = string
      last  = optional(string)
      scope = optional(number)
    })), [])
  }))

lock.tfType:
object({
    kind = string
    name = optional(string, null)
  })

monitor_config.tfType:
object({
    protocol                     = string
    port                         = number
    path                         = optional(string, "/")
    interval_in_seconds          = optional(number, 30)
    timeout_in_seconds           = optional(number, 10)
    tolerated_number_of_failures = optional(number, 3)
    custom_headers = optional(list(object({
      name  = string
      value = string
    })), [])
    expected_status_code_ranges = optional(list(object({
      min = number
      max = number
    })), [])
  })
